// Library Header: a constexpr function is part of the API
namespace MathLib {
  constexpr int square(int n) {
    // In V2, we add logging, which is not constexpr-compatible
    // std::cout << "Calculating square of " << n << '\n'; // This would break client code
    return n * n;
  }
}

// Client Code: relies on the API's constexpr guarantee
#include <array>

constexpr int side_length = 5;
// The size of this array MUST be a compile-time constant.
// This is only possible because MathLib::square is constexpr.
std::array<int, MathLib::square(side_length)> my_compile_time_array; // Size is 25

// If MathLib::square were to lose its constexpr specifier,
// this line would immediately fail to compile.
